exercises.answer:
Checkout depends on a contract, while each policy owns its formula. Add a new policy without changing Checkout. A conditional can be clearer for a small set of stable rules.

```cpp
#include <iostream>
struct ShippingPolicy {
    virtual int quote(int weight) const = 0;
    virtual ~ShippingPolicy() = default;
};
struct Standard : ShippingPolicy {
    int quote(int weight) const override { return 5 + 2 * weight; }
};
struct Express : ShippingPolicy {
    int quote(int weight) const override { return 10 + 4 * weight; }
};
struct Pickup : ShippingPolicy {
    int quote(int) const override { return 0; }
};
class Checkout {
    const ShippingPolicy& policy;
public:
    explicit Checkout(const ShippingPolicy& selected) : policy(selected) {}
    int total(int subtotal, int weight) const { return subtotal + policy.quote(weight); }
};
int main() {
    Standard standard;
    Express express;
    Pickup pickup;
    std::cout << "Standard: " << Checkout(standard).total(100, 3) << '\n';
    std::cout << "Express: " << Checkout(express).total(100, 3) << '\n';
    std::cout << "Pickup: " << Checkout(pickup).total(100, 3) << '\n';
}
