The adapter translates an existing interface into the one the caller expects. It holds a reference, so the legacy sensor must outlive it.

```cpp
#include <iostream>
class LegacySensor {
public:
    int readCelsius() const { return 25; }
};
struct TemperatureSource {
    virtual double fahrenheit() const = 0;
    virtual ~TemperatureSource() = default;
};
class SensorAdapter : public TemperatureSource {
    const LegacySensor& sensor;
public:
    explicit SensorAdapter(const LegacySensor& source) : sensor(source) {}
    double fahrenheit() const override { return sensor.readCelsius() * 9.0 / 5.0 + 32; }
};
void display(const TemperatureSource& source) {
    std::cout << "Temperature: " << source.fahrenheit() << " F\n";
}
int main() {
    LegacySensor sensor;
    SensorAdapter adapter(sensor);
    display(adapter);
}
