exercises.answer:
Inventory publishes through the Observer contract without knowing display types. This example uses non-owning pointers; observers must unsubscribe before destruction. Notifications are synchronous, and mutation during callbacks is outside this exercise.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
struct Observer {
    virtual void update(int stock) = 0;
    virtual ~Observer() = default;
};
class Inventory {
    std::vector<Observer*> observers;
public:
    void subscribe(Observer& observer) {
        if (std::find(observers.begin(), observers.end(), &observer) == observers.end())
            observers.push_back(&observer);
    }
    void unsubscribe(Observer& observer) {
        observers.erase(std::remove(observers.begin(), observers.end(), &observer), observers.end());
    }
    void setStock(int stock) {
        for (auto* observer : observers) observer->update(stock);
    }
};
class Display : public Observer {
    const char* name;
public:
    explicit Display(const char* label) : name(label) {}
    void update(int stock) override { std::cout << name << ": " << stock << '\n'; }
};
int main() {
    Display dashboard("Dashboard"), alert("Alert");
    Inventory inventory;
    inventory.subscribe(dashboard);
    inventory.subscribe(alert);
    inventory.subscribe(dashboard); // Duplicate subscriptions are ignored.
    inventory.setStock(3);
    inventory.unsubscribe(alert);
    inventory.setStock(0);
}
